<?php
declare(strict_types=1); require_once __DIR__.'/bootstrap.php'; $u=require_login(); if($_SERVER['REQUEST_METHOD']!=='POST')redirect('subindicator_workflow.php'); verify_csrf(); $id=(int)($_POST['submission_id']??0);$action=(string)($_POST['action']??'');$target=(string)($_POST['target_state']??'');$pdo=db();
$st=$pdo->prepare("SELECT s.*,p.project_code,si.code sub_code,i.code geb_code,u.email submitter_email,u.name submitter_name,r.email reviewer_email,a.email approver_email FROM subindicator_submissions s JOIN projects p ON p.id=s.project_id JOIN sub_indicators si ON si.id=s.sub_indicator_id LEFT JOIN indicators i ON i.id=s.geb_indicator_id JOIN users u ON u.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id WHERE s.id=?");$st->execute([$id]);$rec=$st->fetch();if(!$rec){flash('danger','Sub-indicator record not found.');redirect('subindicator_workflow.php');}
if(!can_route($u['role'])){flash('danger','You are not authorized to route workflow records.');redirect('subindicator.php?id='.$id);}if($action!=='move_to'||!in_array($target,['draft','review','approval','approved'],true)){flash('danger','Invalid workflow destination.');redirect('subindicator.php?id='.$id);}if($target===$rec['state']){flash('warning','The record is already in '.workflow_label($target).'.');redirect('subindicator.php?id='.$id);}
$from=$rec['state'];$labels=['draft'=>'Moved to Draft','review'=>'Moved to Review','approval'=>'Moved to Approval','approved'=>'Moved to Completed'];$pdo->prepare("UPDATE subindicator_submissions SET state=?,updated_at=NOW(),approved_at=? WHERE id=?")->execute([$target,$target==='approved'?date('Y-m-d H:i:s'):null,$id]);subindicator_audit($id,(int)$u['id'],$labels[$target],$from,$target,'Workflow transition completed by '.$u['name'].'.');
flash('success','Workflow action completed. The sub-indicator record is now '.workflow_label($target).'.');redirect('subindicator.php?id='.$id);
